class PaymentDataProcessor {
    private $pdo;

    public function __construct($pdoConnection) {
        $this->pdo = $pdoConnection;
    }

    public function getPaymentDetails($input) {
        $identifier = strstr($input, '_', true) ?: $input;
        $stmt = $this->pdo->prepare("SELECT * FROM payments WHERE transaction_id LIKE :identifier");
        $stmt->bindValue(':identifier', $identifier . '%', PDO::PARAM_STR);
        $stmt->execute();
        $records =  $stmt->fetchAll(PDO::FETCH_ASSOC);
        return $records;
    }
}
```

